mapper.select:
SELECT COUNT(*) FROM passkey_bootstrap_confirmation_token
WHERE user_id = #{userId}
  AND created_at > DATE_SUB(UTC_TIMESTAMP(), INTERVAL #{withinSeconds} SECOND)

mapper.update:
UPDATE passkey_bootstrap_confirmation_token
SET consumed_at = UTC_TIMESTAMP()
WHERE token_hash = #{tokenHash}
  AND user_id = #{userId}
  AND session_primary_id = #{sessionPrimaryId}
  AND consumed_at IS NULL
  AND expires_at > UTC_TIMESTAMP()
